local rows={}
for _,group in ipairs(groups)do
  for _,cell in ipairs(group.cells)do
    local row={id=cell[1],quadrant=cell[2],sourceCells=cell[3],sourceFiles=files[group.files]}
    for key,value in pairs(group)do
      if key~='files' and key~='art' and key~='cells' then row[key]=value end
    end
    for key,value in pairs(art[group.art])do row[key]=value end
    rows[#rows+1]=row
  end
end
return rows

end)()
local function key(r)return r.game..":"..(r.map or"*")..":"..r.id..":"..r.quadrant..":"..tostring(r.x)..":"..tostring(r.y)end
local lookup={}
for _,r in ipairs(fixes)do assert(not lookup[key(r)]);lookup[key(r)]=r end
local n=0
for i,r in ipairs(rows)do if lookup[key(r)]then rows[i]=lookup[key(r)];lookup[key(r)]=nil;n=n+1 end end
assert(n==28 and next(lookup)==nil,"Game Corner exact counter supersession changed")
end
-- END COMPLETE NATIVE CRYSTALDUST GOLDENROD COUNTERS
return rows
